using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.Data.SqlClient;
public partial class frmProductos : System.Web.UI.Page { string connectionString = @"Server=.\sqlexpress; Database=productos; Trusted_Connection=True;"; bool nuevo; protected void Page_Load(object sender, EventArgs e) { if (!IsPostBack) { btnNuevo.Enabled = true; btnGuardar.Enabled = false; btnCancelar.Enabled = false; btnEliminar.Enabled = false; txtId.Enabled = false; txtNombre.Enabled = false; txtPrecio.Enabled = false; txtStock.Enabled = false; } } protected void btnNuevo_Click(object sender, EventArgs e) { btnNuevo.Enabled = false; btnGuardar.Enabled = true; btnCancelar.Enabled = true; btnEliminar.Enabled = false; txtNombre.Enabled = true; txtPrecio.Enabled = true; txtStock.Enabled = true; txtNombre.Focus(); nuevo = true; } protected void btnGuardar_Click(object sender, EventArgs e) { SqlConnection con = new SqlConnection(connectionString); con.Open(); try { SqlCommand cmd; if (nuevo) { string sql = "INSERT INTO LAPTOPS (NOMBRE, PRECIO, STOCK) VALUES (@N, @P, @S)"; cmd = new SqlCommand(sql, con); cmd.Parameters.AddWithValue("@N", txtNombre.Text); cmd.Parameters.AddWithValue("@P", txtPrecio.Text); cmd.Parameters.AddWithValue("@S", txtStock.Text); cmd.ExecuteNonQuery(); Response.Write("<script>alert('Registro ingresado correctamente');</script>"); } else { string sql = "UPDATE LAPTOPS SET NOMBRE=@N, PRECIO=@P, STOCK=@S WHERE ID=@ID"; cmd = new SqlCommand(sql, con); cmd.Parameters.AddWithValue("@N", txtNombre.Text); cmd.Parameters.AddWithValue("@P", txtPrecio.Text); cmd.Parameters.AddWithValue("@S", txtStock.Text); cmd.Parameters.AddWithValue("@ID", txtId.Text); cmd.ExecuteNonQuery(); Response.Write("<script>alert('Registro actualizado correctamente');</script>"); } } catch (Exception ex) { Response.Write("<script>alert('Error: " + ex.Message + "');</script>"); } finally { con.Close(); } limpiarCampos(); bloquear(); } protected void btnCancelar_Click(object sender, EventArgs e) { limpiarCampos(); bloquear(); } protected void btnEliminar_Click(object sender, EventArgs e) { SqlConnection con = new SqlConnection(connectionString); con.Open(); try { string sql = "DELETE FROM LAPTOPS WHERE ID=@ID"; SqlCommand cmd = new SqlCommand(sql, con); cmd.Parameters.AddWithValue("@ID", txtId.Text); cmd.ExecuteNonQuery(); Response.Write("<script>alert('Registro eliminado correctamente');</script>"); } catch (Exception ex) { Response.Write("<script>alert('Error: " + ex.Message + "');</script>"); } finally { con.Close(); } limpiarCampos(); bloquear(); } protected void btnBuscar_Click(object sender, EventArgs e) { SqlConnection con = new SqlConnection(connectionString); con.Open(); try { string sql = "SELECT * FROM LAPTOPS WHERE ID=@ID"; SqlCommand cmd = new SqlCommand(sql, con); cmd.Parameters.AddWithValue("@ID", txtBuscarId.Text); SqlDataReader reader = cmd.ExecuteReader(); if (reader.Read()) { txtId.Text = reader["ID"].ToString(); txtNombre.Text = reader["NOMBRE"].ToString(); txtPrecio.Text = reader["PRECIO"].ToString(); txtStock.Text = reader["STOCK"].ToString(); desbloquearEdicion(); nuevo = false; } else Response.Write("<script>alert('No se encontró registro');</script>"); } finally { con.Close(); } } void limpiarCampos() { txtId.Text = ""; txtNombre.Text = ""; txtPrecio.Text = ""; txtStock.Text = ""; txtBuscarId.Text = ""; } void bloquear() { btnNuevo.Enabled = true; btnGuardar.Enabled = false; btnCancelar.Enabled = false; btnEliminar.Enabled = false; txtNombre.Enabled = false; txtPrecio.Enabled = false; txtStock.Enabled = false; } void desbloquearEdicion() { btnNuevo.Enabled = false; btnGuardar.Enabled = true; btnCancelar.Enabled = true; btnEliminar.Enabled = true; txtNombre.Enabled = true; txtPrecio.Enabled = true; txtStock.Enabled = true; } }